// Regla de enrutamiento: lo rutinario se queda en el modelo local;
// los reclamos, lo urgente y lo que no se pudo clasificar van a la nube.

let clasificado = false;
let clasificacion = { intencion: 'otro', urgente: false };
let ruta = 'nube';

try {
  // Intentar parsear la respuesta del modelo local
  const contenido = $input.first().json.choices?.[0]?.message?.content;

  if (contenido) {
    clasificacion = JSON.parse(contenido);
    clasificado = true;
  }
} catch (e) {
  // Si falla el parseo, se queda con valores por defecto
  clasificado = false;
}

const delicado = clasificacion.urgente || ['reclamo', 'otro'].includes(clasificacion.intencion);
ruta = !clasificado || delicado ? 'nube' : 'local';

// Obtener datos del nodo Config
const config = $('Config').first().json;

return {
  mensaje: config.mensaje,
  local_url: config.local_url,
  local_modelo: config.local_modelo,
  nube_url: config.nube_url,
  nube_modelo: config.nube_modelo,
  nube_razonamiento: config.nube_razonamiento,
  precio_entrada: config.precio_entrada,
  precio_salida: config.precio_salida,
  prompt_asistente: config.prompt_asistente,
  inicio: config.inicio,
  clasificacion: clasificacion,
  clasificado: clasificado,
  ruta: ruta
};
